struct Queue {
    items: Vec<Int>,
}

impl Queue {
    fn new() -> Self {
        Queue { items: vec![] }
    }

    fn push(&mut self, item: Int) {
        self.items.push(item);
    }

    fn pop(&mut self) -> Option<Int> {
        if let Some(first) = self.items.remove(0) {
            Some(first)
        } else {
            None
        }
    }

    fn peek(&self) -> &Int {
        &self.items[0]
    }

    fn exchange(&mut self) {
        let first_item = self.pop().unwrap();
        self.items.push(first_item);
    }

    fn print_queue(&self) {
        for item in &self.items {
            println!("{}", item);
        }
    }
}

